import React from 'react';

import Section from '../section';

const SectionAbout = ({ about }) => {
  return (
    <Section title="About Me">
      <div className="mb-6">
        {/* the `about` string is a multi-line template literal; without
            whitespace-pre-line HTML collapses its newlines and it renders
            as one run-on paragraph */}
        <p className="whitespace-pre-line">{about.trim()}</p>
      </div>
    </Section>
  );
};

export default SectionAbout;
